widget.solution:
def sanity_flags(m, n_days):
    flags = []
    if m["sharpe"] > 2:
        flags.append("sharpe-above-2")
    if m["max_drawdown"] > -0.01:
        flags.append("no-drawdown")
    if m["turnover"] == 0:
        flags.append("turnover-zero")
    if n_days < 252:
        flags.append("too-short")
    if m["hit_rate"] > 0.6:
        flags.append("hit-rate-above-0.6")
    return sorted(flags)

