widget.solution:
def find_the_bug(engines, bars):
    n = len(bars)
    cuts = [n // 4, n // 2, 3 * n // 4]
    bad = []
    for name, run in engines.items():
        leaks = not all(lookahead_check(run, bars, cut) for cut in cuts)
        paid = run(bars)["cost"].sum() < 0          # costs credited, not charged
        if leaks or paid:
            bad.append(name)
    return sorted(bad)
